import React, { useState } from 'react';
import { Outlet, Link, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import {
    LayoutDashboard, Calendar, CalendarDays, BarChart3,
    LogOut, User, Menu, X, Flame, Award, Target
} from 'lucide-react';

const Layout = () => {
    const { user, logout } = useAuth();
    const location = useLocation();
    const navigate = useNavigate();
    const [sidebarOpen, setSidebarOpen] = useState(false);

    const navigation = [
        { name: 'Dashboard', href: '/dashboard', icon: LayoutDashboard },
        { name: 'Daily Tracker', href: '/tracker', icon: Calendar },
        { name: 'Roadmap', href: '/weekly-focus', icon: CalendarDays },
        { name: 'Progress', href: '/progress', icon: BarChart3 },
    ];

    const handleLogout = () => {
        logout();
        navigate('/login');
    };

    return (
        <div className="min-h-screen bg-dark-primary flex">
            {/* Mobile sidebar */}
            {sidebarOpen && (
                <div className="fixed inset-0 z-50 lg:hidden">
                    <div className="fixed inset-0 bg-black/70" onClick={() => setSidebarOpen(false)} />
                    <div className="fixed inset-y-0 left-0 w-72 bg-dark-card border-r border-dark-border shadow-2xl">
                        <div className="flex items-center justify-between p-4 border-b border-dark-border">
                            <span className="text-xl font-bold gradient-text">🚀 RoadMap</span>
                            <button onClick={() => setSidebarOpen(false)} className="p-2 text-light-secondary hover:text-white">
                                <X size={20} />
                            </button>
                        </div>
                        <nav className="p-4 space-y-1">
                            {navigation.map((item) => {
                                const isActive = location.pathname === item.href;
                                return (
                                    <Link
                                        key={item.name}
                                        to={item.href}
                                        onClick={() => setSidebarOpen(false)}
                                        className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
                                            isActive
                                                ? 'bg-gradient-main text-white'
                                                : 'text-light-secondary hover:bg-dark-hover hover:text-white'
                                        }`}
                                    >
                                        <item.icon size={20} />
                                        {item.name}
                                    </Link>
                                );
                            })}
                            <button
                                onClick={handleLogout}
                                className="flex items-center gap-3 px-4 py-3 rounded-xl text-red-400 hover:bg-red-500/10 hover:text-red-300 w-full transition-all mt-4"
                            >
                                <LogOut size={20} />
                                Logout
                            </button>
                        </nav>
                    </div>
                </div>
            )}

            {/* Desktop sidebar */}
            <div className="hidden lg:fixed lg:inset-y-0 lg:flex lg:w-72">
                <div className="flex flex-col flex-1 bg-dark-card border-r border-dark-border h-screen">
                    <div className="flex items-center gap-2 px-6 h-16 border-b border-dark-border">
                        <span className="text-2xl">🚀</span>
                        <span className="text-xl font-bold gradient-text">RoadMap</span>
                        <span className="text-xs bg-gradient-main text-white px-2 py-0.5 rounded-full ml-1">Beta</span>
                    </div>
                    <nav className="flex-1 px-4 py-6 space-y-1 overflow-y-auto">
                        {navigation.map((item) => {
                            const isActive = location.pathname === item.href;
                            return (
                                <Link
                                    key={item.name}
                                    to={item.href}
                                    className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
                                        isActive
                                            ? 'bg-gradient-main text-white'
                                            : 'text-light-secondary hover:bg-dark-hover hover:text-white'
                                    }`}
                                >
                                    <item.icon size={20} />
                                    {item.name}
                                </Link>
                            );
                        })}
                    </nav>
                    <div className="border-t border-dark-border p-4">
                        <div className="flex items-center gap-3 px-4 py-3 bg-dark-secondary rounded-xl">
                            <div className="w-8 h-8 rounded-full bg-gradient-main flex items-center justify-center">
                                <User size={16} className="text-white" />
                            </div>
                            <div className="flex-1 min-w-0">
                                <p className="text-sm font-medium text-white truncate">
                                    {user?.fullName || user?.username}
                                </p>
                                <p className="text-xs text-light-muted truncate">{user?.email}</p>
                            </div>
                        </div>
                        <button
                            onClick={handleLogout}
                            className="flex items-center gap-3 px-4 py-3 rounded-xl text-red-400 hover:bg-red-500/10 hover:text-red-300 w-full transition-all mt-2"
                        >
                            <LogOut size={20} />
                            Logout
                        </button>
                    </div>
                </div>
            </div>

            {/* Main content - FULL WIDTH */}
            <div className="flex-1 lg:ml-72 min-h-screen">
                {/* Mobile header */}
                <div className="lg:hidden sticky top-0 z-40 bg-dark-card border-b border-dark-border px-4 py-3 flex items-center justify-between">
                    <button onClick={() => setSidebarOpen(true)} className="p-2 text-light-secondary hover:text-white">
                        <Menu size={24} />
                    </button>
                    <span className="text-xl font-bold gradient-text">🚀 RoadMap</span>
                    <div className="w-10"></div>
                </div>

                <main className="p-4 md:p-6 lg:p-8 w-full">
                    <Outlet />
                </main>
            </div>
        </div>
    );
};

export default Layout;
